pub const string_pkg = @import("../string/string.zig");
pub const shell = @import("../shell/shell.zig");
pub const bun = @import("bun");
pub const ParserError = error{
    OutOfMemory,
    UnexpectedToken,
};

pub const ExpandError = error{
    OutOfMemory,
    UnexpectedToken,
};

pub fn DeinitWithAllocGuard(comptime T: type) type {
    return struct {
        val: T,
        alloc: Allocator,
        __cp_dropped: bool = false,

pub fn __cp_deinit(self: *@This()) void {
            if (self.__cp_dropped) return;
            self.__cp_dropped = true;
                _ = self.val.deinit(self.alloc);
        }
    };
}

pub const ExpansionVariant = packed struct(u32) {
    start: u16 = 0,
    end: u16 = 0,
};

pub const _TokenExpansionVariants = struct {
    idx: u16 = 0,
    end: u16 = 0,
};

pub const Token = union(enum) {
    open: _TokenExpansionVariants,
    comma: void,
    text: SmolStr,
    close: void,
    eof: void,

pub fn toText(self: Token) SmolStr {
            return (switch (self) {
.open => SmolStr.fromChar(123),
.comma => SmolStr.fromChar(44),
.text => |txt| txt,
.close => SmolStr.fromChar(125),
.eof => SmolStr.empty(),
});
    }
    const Tag = @typeInfo(Token).@"union".tag_type.?;
    const ExpansionVariants = _TokenExpansionVariants;
};

pub const _AST_Atom = union(enum) {
    text: SmolStr,
    expansion: _AST_Expansion,
};

pub const _AST_Atoms = union(enum) {
    single: _AST_Atom,
    many: []_AST_Atom,
};

pub const _AST_Group = struct {
    bubble_up: ?*_AST_Group = null,
    bubble_up_next: ?u16 = null,
    atoms: _AST_Atoms,
};

pub const _AST_Expansion = struct {
    variants: []_AST_Group,
};

pub const AST = struct {
    pub const Atom = _AST_Atom;
    pub const Group = _AST_Group;
    pub const Expansion = _AST_Expansion;
};

pub const ParserErrorMsg = struct {
    msg: []const u8,
};

pub const Parser = struct {
    current: usize = 0,
    tokens: []const Token,
    alloc: Allocator,
    errors: std.array_list.Managed(ParserErrorMsg),

pub fn init(tokens: []const Token, alloc: Allocator) Parser {
            return .{ .tokens = tokens, .alloc = alloc, .errors = std.array_list.Managed(ParserErrorMsg).init(alloc) };
    }

pub fn parse(self: *Parser) !AST.Group {
            var group_alloc_ = std.heap.stackFallback(@sizeOf(AST.Atom), self.alloc);
            _ = &group_alloc_;
            const group_alloc = group_alloc_.get();
            var nodes = std.array_list.Managed(AST.Atom).init(group_alloc);
            _ = &nodes;
            while ((!self.matchTok(.eof))) {
                var opt_atom = try self.parseAtom();
                _ = &opt_atom;
                if ((opt_atom == null)) {
                    break;
                }
                _ = try nodes.append(opt_atom.?);
            }
            if ((nodes.items.len == 1)) {
                return .{ .atoms = .{ .single = nodes.items[0] } };
            } else {
                return .{ .atoms = .{ .many = nodes.items[0..] } };
            }
    }

pub fn parseAtom(self: *Parser) ParserError!?AST.Atom {
            switch (self.advance()) {
.open => {
const expansion_ptr = try self.parseExpansion();
            return .{ .expansion = expansion_ptr };
},
.text => |txt| {
return .{ .text = txt };
},
.eof => {
return null;
},
.close, .comma => {
return error.UnexpectedToken;
},
}
    }

pub fn parseExpansion(self: *Parser) !AST.Expansion {
            var variants = std.array_list.Managed(AST.Group).init(self.alloc);
            _ = &variants;
            const close_eof: [2]Token.Tag = .{ .close, .eof };
            while ((!self.match_any((&close_eof)))) {
                if (self.matchTok(.eof)) {
                    break;
                }
                var group_alloc_ = std.heap.stackFallback(@sizeOf(AST.Atom), self.alloc);
                _ = &group_alloc_;
                const group_alloc = group_alloc_.get();
                var group = std.array_list.Managed(AST.Atom).init(group_alloc);
                _ = &group;
                var close = false;
                _ = &close;
                while ((!self.matchTok(.eof))) {
                    if (self.matchTok(.close)) {
                        close = true;
                        break;
                    }
                    if (self.matchTok(.comma)) {
                        break;
                    }
                    var opt_atom = try self.parseAtom();
                    _ = &opt_atom;
                    if ((opt_atom == null)) {
                        break;
                    }
                    _ = try group.append(opt_atom.?);
                }
                if ((group.items.len == 1)) {
                    _ = try variants.append(.{ .atoms = .{ .single = group.items[0] } });
                } else {
                    _ = try variants.append(.{ .atoms = .{ .many = group.items[0..] } });
                }
                if (close) {
                    break;
                }
            }
            return .{ .variants = variants.items[0..] };
    }

pub fn has_eq_sign(self: *Parser, str: []const u8) ?u32 {
        _ = self;
            return shell.hasEqSign(str);
    }

pub fn advance(self: *Parser) Token {
            if ((!self.is_at_end())) {
                self.current = (self.current + 1);
            }
            return (if ((self.current > 0)) self.prev() else self.peek());
    }

pub fn is_at_end(self: Parser) bool {
            return (self.peek() == .eof);
    }

pub fn expect(self: *Parser, toktag: Token.Tag) Token {
            _ = assert((toktag == (if (comptime @typeInfo(Token.Tag) == .@"enum") @as(Token.Tag, @enumFromInt(self.peek())) else @as(Token.Tag, self.peek()))));
            if (self.check(toktag)) {
                return self.advance();
            }
            _ = unreachable;
    }

pub fn matchTok(self: *Parser, toktag: Token.Tag) bool {
            if ((std.meta.activeTag(self.peek()) == toktag)) {
                _ = self.advance();
                return true;
            }
            return false;
    }

pub fn match_any2(self: *Parser, comptime toktags: []const Token.Tag) ?Token {
            const peeked = self.peek();
            inline for (toktags) |tag| {
                if ((peeked == tag)) {
                    _ = self.advance();
                    return peeked;
                }
            }
            return null;
    }

pub fn match_any(self: *Parser, comptime toktags: []const Token.Tag) bool {
            const peeked = std.meta.activeTag(self.peek());
            inline for (toktags) |tag| {
                if ((peeked == tag)) {
                    _ = self.advance();
                    return true;
                }
            }
            return false;
    }

pub fn check(self: Parser, toktag: Token.Tag) bool {
            return (std.meta.activeTag(self.peek()) == toktag);
    }

pub fn peek(self: Parser) Token {
            return self.tokens[@as(usize, @intCast(self.current))];
    }

pub fn peek_n(self: Parser, n: u32) Token {
            if (((self.current + n) >= self.tokens.len)) {
                return self.tokens[@as(usize, @intCast((self.tokens.len - 1)))];
            }
            return self.tokens[@as(usize, @intCast((self.current + n)))];
    }

pub fn prev(self: Parser) Token {
            return self.tokens[@as(usize, @intCast((self.current - 1)))];
    }

pub fn add_error(self: *Parser, comptime fmt: []const u8, args: anytype) !void {
            const error_msg = try std.fmt.allocPrint(self.alloc, fmt, args);
            _ = try self.errors.append(.{ .msg = error_msg });
    }
};

pub const _BraceState = struct {
    tok_idx: u16,
    variants: u16,
    prev_tok_end: u16,
};

pub const _StackEntry = struct {
    segment_product: u32 = 1,
    accumulator: u32 = 0,
};

pub const _LexerOutput = struct {
    tokens: ArrayList(Token),
    contains_nested: bool,
};

const log = bun.Output.scoped(.BRACES, .visible);
const MAX_NESTED_BRACES = 10;
pub const Lexer = NewLexer(.ascii);
const SmolStr = string_pkg.SmolStr;
const Encoding = shell.StringEncoding;
const NewChars = shell.ShellCharIter;
const assert = bun.assert;
const ArrayList = std.array_list.Managed;
const Allocator = std.mem.Allocator;
const BraceLexerError = Allocator.Error;

pub fn calculateVariantsAmount(tokens: []const Token) u32 {
        var brace_count: u32 = 0;
        _ = &brace_count;
        var count: u32 = 0;
        _ = &count;
        for (cp_iter_slice(tokens)) |tok| {
            _ = &tok;
            switch (tok) {
.comma => {
count = (count + 1);
},
.open => {
brace_count = (brace_count + 1);
            count = (count + 1);
},
.close => {
brace_count = (brace_count - 1);
},
else => {

},
}
        }
        return count;
}

pub fn buildExpansionTable(tokens: []Token, table: *std.array_list.Managed(ExpansionVariant)) !void {
        const BraceStack = bun.SmallList(_BraceState, MAX_NESTED_BRACES);
        var brace_stack = DeinitWithAllocGuard(BraceStack){ .val = BraceStack{  }, .alloc = bun.default_allocator };
        _ = &brace_stack;
        var __brace_stack_moved = false; _ = &__brace_stack_moved;
        defer if (!__brace_stack_moved) { __brace_stack_moved = true; const __T = @TypeOf(brace_stack); if (@typeInfo(__T) == .optional) { if (brace_stack) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { brace_stack.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = brace_stack; _drop_val.__cp_deinit(); } };
        var i: u16 = 0;
        _ = &i;
        var prev_close = false;
        _ = &prev_close;
        while ((i < tokens.len)) : (i = (i + 1)) {
            switch (tokens[@as(usize, @intCast(i))]) {
.open => {
const table_idx: u16 = @intCast(table.items.len);
            tokens[@as(usize, @intCast(i))].open.idx = table_idx;
            _ = brace_stack.val.append(bun.default_allocator, .{ .tok_idx = i, .variants = 0, .prev_tok_end = i });
},
.close => {
var top = (brace_stack.val.pop()).?;
            _ = &top;
            _ = try table.append(.{ .end = i, .start = (top.prev_tok_end + 1) });
            top.prev_tok_end = i;
            top.variants = (top.variants + 1);
            tokens[@as(usize, @intCast(top.tok_idx))].open.end = @intCast(table.items.len);
            prev_close = true;
},
.comma => {
var top = (brace_stack.val.lastMut()).?;
            _ = &top;
            _ = try table.append(.{ .end = i, .start = (top.prev_tok_end + 1) });
            prev_close = false;
            top.prev_tok_end = i;
            top.variants = (top.variants + 1);
},
else => {
prev_close = false;
},
}
        }
        if (bun.Environment.allow_assert) {
            var kdjsd: usize = 0;
            _ = &kdjsd;
            while ((kdjsd < table.items.len)) : (kdjsd = (kdjsd + 1)) {
                const variant = table.items[@as(usize, @intCast(kdjsd))];
                _ = assert(((variant.start != 0) and (variant.end != 0)));
            }
        }
}

pub fn buildExpansionTableAlloc(alloc: Allocator, tokens: []Token) !std.array_list.Managed(ExpansionVariant) {
        var table = std.array_list.Managed(ExpansionVariant).init(alloc);
        _ = &table;
        _ = try buildExpansionTable(tokens, (&table));
        return table;
}

pub fn expandFlat(tokens: []const Token, expansion_table: []const ExpansionVariant, out: []std.array_list.Managed(u8), out_key: u16, out_key_counter: *u16, depth_: u8, start: usize, end: usize) !void {
        _ = log("expandFlat [{d}, {d}]", .{ start, end });
        if (((start >= tokens.len) or (end > tokens.len))) {
            return;
        }
        var depth = depth_;
        _ = &depth;
        var idx: usize = start;
        _ = &idx;
        while ((idx < end)) : (idx = (idx + 1)) {
            const atom = tokens[@as(usize, @intCast(idx))];
            switch (atom) {
.text => |txt| {
_ = try out[@as(usize, @intCast(out_key))].appendSlice(txt.slice());
},
.close => {
depth = (depth - 1);
},
.open => |expansion_variants| {
depth = (depth + 1);
            if (bun.Environment.allow_assert) {
                _ = assert(((expansion_variants.end - expansion_variants.idx) >= 1));
            }
            var variants = expansion_table[expansion_variants.idx..expansion_variants.end];
            _ = &variants;
            const skip_over_idx = variants[@as(usize, @intCast((variants.len - 1)))].end;
            const starting_len = out[@as(usize, @intCast(out_key))].items.len;
            var i: usize = 0;
            _ = &i;
            while ((i < variants.len)) : (i = (i + 1)) {
                const variant = (&variants[@as(usize, @intCast(i))]);
                var new_key = out_key;
                _ = &new_key;
                if ((i != 0)) {
                    new_key = out_key_counter.*;
                    _ = try out[@as(usize, @intCast(new_key))].appendSlice(out[@as(usize, @intCast(out_key))].items[0..starting_len]);
                    out_key_counter.* = (out_key_counter.* + 1);
                }
                _ = try expandFlat(tokens, expansion_table, out, new_key, out_key_counter, depth, variant.start, variant.end);
                _ = try expandFlat(tokens, expansion_table, out, new_key, out_key_counter, depth, skip_over_idx, end);
            }
            return;
},
else => {

},
}
        }
}

pub fn expandNested(root: *AST.Group, out: []std.array_list.Managed(u8), out_key: u16, out_key_counter: *u16, start: u32) ExpandError!void {
        if ((root.atoms == .single)) {
            if ((start > 0)) {
                if (root.bubble_up) |bubble_up| {
                    _ = &bubble_up;
                    return expandNested(bubble_up, out, out_key, out_key_counter, root.bubble_up_next.?);
                }
                return;
            }
            switch (root.atoms.single) {
.text => |txt| {
_ = try out[@as(usize, @intCast(out_key))].appendSlice(txt.slice());
            if (root.bubble_up) |bubble_up| {
                _ = &bubble_up;
                return expandNested(bubble_up, out, out_key, out_key_counter, root.bubble_up_next.?);
            }
            return;
},
.expansion => |expansion| {
const length = out[@as(usize, @intCast(out_key))].items.len;
            var j: usize = 0;
            _ = &j;
            while ((j < expansion.variants.len)) : (j = (j + 1)) {
                var group = (blk: {
                break :blk (&expansion.variants[@as(usize, @intCast(j))]);

});
                _ = &group;
                group.bubble_up = root;
                group.bubble_up_next = 1;
                var new_key = out_key;
                _ = &new_key;
                if ((j != 0)) {
                    new_key = out_key_counter.*;
                    _ = try out[@as(usize, @intCast(new_key))].appendSlice(out[@as(usize, @intCast(out_key))].items[0..length]);
                    out_key_counter.* = (out_key_counter.* + 1);
                }
                _ = try expandNested(group, out, new_key, out_key_counter, 0);
            }
            return;
},
}
        }
        if ((start >= root.atoms.many.len)) {
            if (root.bubble_up) |bubble_up| {
                _ = &bubble_up;
                return expandNested(bubble_up, out, out_key, out_key_counter, root.bubble_up_next.?);
            }
            return;
        }
        var i_curr: usize = start;
        _ = &i_curr;
        while ((i_curr < root.atoms.many.len)) : (i_curr = (i_curr + 1)) {
            const atom = root.atoms.many[@as(usize, @intCast(i_curr))];
            const i: u16 = @intCast(i_curr);
            switch (atom) {
.text => |txt| {
_ = try out[@as(usize, @intCast(out_key))].appendSlice(txt.slice());
},
.expansion => |expansion| {
const length = out[@as(usize, @intCast(out_key))].items.len;
            var j: usize = 0;
            _ = &j;
            while ((j < expansion.variants.len)) : (j = (j + 1)) {
                var group = (blk: {
                break :blk (&expansion.variants[@as(usize, @intCast(j))]);

});
                _ = &group;
                group.bubble_up = root;
                group.bubble_up_next = (i + 1);
                var new_key = out_key;
                _ = &new_key;
                if ((j != 0)) {
                    new_key = out_key_counter.*;
                    _ = try out[@as(usize, @intCast(new_key))].appendSlice(out[@as(usize, @intCast(out_key))].items[0..length]);
                    out_key_counter.* = (out_key_counter.* + 1);
                }
                _ = try expandNested(group, out, new_key, out_key_counter, 0);
            }
            return;
},
}
        }
        if (root.bubble_up) |bubble_up| {
            _ = &bubble_up;
            return try expandNested(bubble_up, out, out_key, out_key_counter, root.bubble_up_next.?);
        }
}

pub fn expand(allocator: Allocator, tokens: []Token, out: []std.array_list.Managed(u8), contains_nested: bool) ExpandError!void {
        var out_key_counter: u16 = 1;
        _ = &out_key_counter;
        if ((!contains_nested)) {
            var expansions_table = try buildExpansionTableAlloc(allocator, tokens);
            _ = &expansions_table;
            return try expandFlat(tokens, expansions_table.items[0..], out, 0, (&out_key_counter), 0, 0, tokens.len);
        }
        var parser = Parser.init(tokens, allocator);
        _ = &parser;
        var root_node = try parser.parse();
        _ = &root_node;
        _ = try expandNested((blk: {
        break :blk (&root_node);

}), out, 0, (&out_key_counter), 0);
}

