pub fn NewLexer(comptime encoding: Encoding) type {
        const Chars = NewChars(encoding);
        return struct {
    chars: Chars,
    alloc: Allocator,
    tokens: ArrayList(Token),
    contains_nested: bool = false,

pub fn tokenize(alloc: Allocator, src: []const u8) BraceLexerError!Output {
            var lexer = Self{ .chars = Chars.init(src), .tokens = ArrayList(Token).init(alloc), .alloc = alloc };
            _ = &lexer;
            const contains_nested = try lexer.tokenize_impl();
            return Output{ .tokens = lexer.tokens, .contains_nested = contains_nested };
    }

pub fn tokenize_impl(self: *@This()) BraceLexerError!bool {
            const BraceStack = bun.SmallList(u32, MAX_NESTED_BRACES);
            var brace_stack = DeinitWithAllocGuard(BraceStack){ .val = BraceStack{  }, .alloc = bun.default_allocator };
            _ = &brace_stack;
            var __brace_stack_moved = false; _ = &__brace_stack_moved;
            defer if (!__brace_stack_moved) { __brace_stack_moved = true; const __T = @TypeOf(brace_stack); if (@typeInfo(__T) == .optional) { if (brace_stack) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { brace_stack.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = brace_stack; _drop_val.__cp_deinit(); } };
            while (true) {
                var input_opt = self.eat();
                _ = &input_opt;
                if ((input_opt == null)) {
                    break;
                }
                const input = input_opt.?;
                const char = input.char;
                const escaped = input.escaped;
                if ((!escaped)) {
                    switch (char) {
'{' => {
_ = brace_stack.val.append(bun.default_allocator, @intCast(self.tokens.items.len));
                    _ = try self.tokens.append(.{ .open = .{} });
                    continue;
},
'}' => {
if ((brace_stack.val.len() > 0)) {
                        _ = brace_stack.val.pop();
                        _ = try self.tokens.append(.close);
                        continue;
                    }
},
',' => {
if ((brace_stack.val.len() > 0)) {
                        _ = try self.tokens.append(.comma);
                        continue;
                    }
},
else => {

},
}
                }
                _ = try self.appendChar(char);
            }
            while ((brace_stack.val.len() > 0)) {
                const top_idx = (brace_stack.val.pop()).?;
                _ = self.rollbackBraces(top_idx);
            }
            _ = try self.flattenTokens();
            _ = try self.tokens.append(.eof);
            return self.contains_nested;
    }

pub fn flattenTokens(self: *@This()) Allocator.Error!void {
            if ((self.tokens.items.len == 0)) {
                return;
            }
            var brace_count: u32 = (if ((self.tokens.items[0] == .open)) 1 else 0);
            _ = &brace_count;
            var i: u32 = 0;
            _ = &i;
            var j: u32 = 1;
            _ = &j;
            while (((i < self.tokens.items.len) and (j < self.tokens.items.len))) {
                var itok = (&self.tokens.items[@as(usize, @intCast(i))]);
                _ = &itok;
                var jtok = (&self.tokens.items[@as(usize, @intCast(j))]);
                _ = &jtok;
                if (((itok.* == .text) and (jtok.* == .text))) {
                    _ = try itok.text.appendSlice(self.alloc, jtok.toText().slice());
                    _ = self.tokens.orderedRemove(j);
                } else {
                    if ((jtok.* == .close)) {
                        brace_count = (brace_count - 1);
                    } else {
                        if ((jtok.* == .open)) {
                            brace_count = (brace_count + 1);
                            if ((brace_count > 1)) {
                                self.contains_nested = true;
                            }
                        }
                    }
                    i = (i + 1);
                    j = (j + 1);
                }
            }
    }

pub fn rollbackBraces(self: *@This(), starting_idx: u32) void {
            if (bun.Environment.allow_assert) {
